// One-paragraph summary per year, shown under the title on best-of-year.html.
// Written to describe the albums actually on each list, so revisit the text when a
// year's selections change substantially.
const YEAR_NOTES = {
  "1954": "Connie Converse was writing what would later be called singer-songwriter songs - first person, self-accompanied, quietly devastating - in a Greenwich Village kitchen years before anyone had a name for the form. How Sad, How Lovely was taped by friends on a home machine and went unreleased for half a century. She packed a car in 1974 and was never heard from again.",
  "1955": "Julie Is Her Name is a voice, Barney Kessel's guitar and Ray Leatherwood's bass, and nothing else at all. 'Cry Me a River' made it a hit, but the arrangement is why it lasted - proof that a pop record could be three people and a great deal of empty room.",
  "1956": "Elvis Presley's first album for RCA, half of it Sun leftovers and half new Nashville sessions, and still the loudest argument for the LP as a rock and roll format rather than a singles dumping ground. The cover has been copied so often it has stopped reading as a quotation.",
  "1959": "Kind of Blue and Mingus Ah Um came out months apart on the same label and proposed two different escapes from bebop's chord changes: Miles opened the harmony out into modes and let the band breathe, Mingus went the other way into gospel, blues and collective noise. Most of what followed picks one door or the other.",
  "1960": "Three records looking outward. Miriam Makeba introduced South African song to an American audience with no context for it, Joan Baez did much the same for the Child ballads, and Sketches of Spain had Miles Davis and Gil Evans rebuilding Rodrigo for flugelhorn and orchestra.",
  "1961": "Eastern Sounds puts oboe next to Chinese globular flute and rabab without treating any of it as exotica - a jazz record made by someone who had actually listened rather than gone shopping. Patsy Cline's Showcase is the opposite kind of achievement: Owen Bradley's strings, no wasted motion, every phrase landing exactly where it should.",
  "1962": "American regional music at full strength and mostly instrumental. Booker T. Jones was seventeen when Green Onions was cut in a spare hour at Stax, Dick Dale was running Middle Eastern scales through a Fender amp loud enough to destroy it, and the Beach Boys' first album is still mostly about cars.",
  "1963": "Girl-group pop as a production art. Spector spent a fortune on a Christmas record nobody bought that year and it has outlived nearly everything else he did, while Lesley Gore gave teenage grievance its own genre. Off to one side entirely, Sandy Bull was playing banjo like a raga instrument on a solo album with no audience waiting for it.",
  "1964": "The Ronettes' only album, arriving long after the singles had done the work - Ronnie Bennett's voice set against Spector's wall - and Dionne Warwick making the Bacharach and David songbook sound like conversation. Bob Dylan spent the same twelve months deciding the folk revival was too small a room to stay in.",
  "1965": "A Love Supreme is a devotional suite in four parts and it more or less ends the argument about whether jazz could be a spiritual practice. The rest of the year is first albums: Bert Jansch's guitar, the Sonics screaming through a two-track in Tacoma, Herbie Hancock making hard bop sound weightless.",
  "1966": "Brian Wilson stopped touring and built Pet Sounds in the studio like a piece of architecture, and pop spent the next decade catching up to it. Nina Simone was reinterpreting show tunes and Brel with total authority, and Donovan was hiring session players who would shortly go off and invent something much heavier.",
  "1967": "Two records made in the same city with nothing in common but commercial failure: Sgt. Pepper was the year's monument, the Velvet Underground and Nico's debut was its actual future. Leonard Cohen arrived fully formed at thirty-two, Love made Forever Changes as the sunshine curdled, and Chelsea Girl sits somewhere between all of them.",
  "1968": "Songwriting turned ambitious and strange at once. Laura Nyro and Bobbie Gentry both made records too idiosyncratic for the charts that had just taken them in, Van Morrison cut Astral Weeks with jazz players in a couple of days, and in Sao Paulo Os Mutantes and Caetano Veloso turned Tropicalia into a national argument.",
  "1969": "Everyone stretched out at once. Miles Davis let a tape splice do the composing on In a Silent Way, Isaac Hayes gave four songs forty-five minutes, Pharoah Sanders let Karma run past thirty, and both Tommy and Arthur tried to make the LP carry a plot. Nick Drake and the Stooges debuted at opposite ends of the same twelve months, and the Shaggs recorded Philosophy of the World without being able to play - which somehow belongs here too.",
  "1970": "Singer-songwriters everywhere, and the ones that lasted were at the margins: Linda Perhacs made Parallelograms while working as a dental hygienist, Vashti Bunyan made Just Another Diamond Day at the end of a two-year horse-drawn journey to the Hebrides, and both then disappeared for thirty years. Miles Davis, meanwhile, plugged in and stopped sounding like jazz.",
  "1971": "The confessional album at its peak - Blue, Tapestry, Judee Sill's debut - and simultaneously the year German rock stopped referring to anything Anglo-American. Tago Mago runs on Jaki Liebezeit's drumming and a lot of tape editing; Maggot Brain opens with ten minutes of Eddie Hazel and very little else.",
  "1972": "Clube da Esquina is a double album by two friends from Minas Gerais that folds Beatles harmony, jazz and Brazilian folk into something with no genre to file it under. Nick Drake recorded Pink Moon alone in two nights and left the tapes at Island's front desk. Big Star's #1 Record sold nothing and became the founding document of power pop.",
  "1973": "The studio as instrument, at every budget. Dark Side of the Moon stayed on the chart for a decade, Innervisions has Stevie Wonder playing very nearly everything himself, and Phaedra was built around a sequencer that kept drifting out of tune. Judee Sill's second album is the year's quietest and least-heard.",
  "1974": "Kraftwerk found the loop. Autobahn's title track is twenty-two minutes of motorik going nowhere in particular and it opened a door most of the next twenty years walked through. Robert Wyatt made Rock Bottom after the fall that paralysed him, Gil Scott-Heron and Brian Jackson named the decade's mood, and Radio City went unsold exactly like the last one.",
  "1975": "Brian Eno stopped writing songs and started writing systems - Another Green World is mostly instrumental and largely generated by rules - while Patti Smith opened Horses by rewriting someone else's hymn and turned criticism into a form of rock. Keith Jarrett improvised the Koln Concert late at night on a piano that was not the one he had asked for.",
  "1976": "Punk arrived as a compression algorithm: Ramones is fourteen songs in twenty-nine minutes and every one is the same idea perfected. At the far end of the same year Steve Reich finished Music for 18 Musicians, Joni Mitchell wrote Hejira crossing America by car, and Jorge Ben ran samba through funk.",
  "1977": "Punk's year, and also the year everyone escaped it. Marquee Moon has guitar solos and eleven-minute songs, Pink Flag has neither, and Bowie and Eno were in Berlin giving a whole album side over to instrumentals. Trans-Europe Express would be sampled into the birth of hip-hop within five years.",
  "1978": "Post-punk got its name and its method - Pere Ubu, Siouxsie and the Banshees and Talking Heads all working out what to do with the space punk had cleared. Eno called Music for Airports 'ambient' and founded a genre largely by writing its liner notes, while Big Star's Third finally surfaced four years after the band fell apart.",
  "1979": "The most productive year post-punk had. Gang of Four made funk sound like an argument, This Heat recorded in a disused meat pie factory, Young Marble Giants took nearly everything out, and Public Image Ltd. dismantled the band Lydon had just become famous for. Chic and Off the Wall were doing something else entirely and doing it better than anyone.",
  "1980": "Interior records. Closer was finished before Ian Curtis died and released after, Seventeen Seconds began the Cure's grey period, and Vini Reilly's guitar barely raises its voice for the length of an album. Eno and Harold Budd's Ambient 2 is where ambient stopped being a provocation and became somewhere to live.",
  "1981": "Synthesizers stopped being futuristic and became furniture - Dare is a pop record made by people who could not play, Computer World is Kraftwerk at their funniest and most prescient. In America, Mission of Burma and the Wipers were building the loud, tuneful, self-released template that hardcore's smarter children would inherit.",
  "1982": "Milo Goes to College is twenty-two minutes about being a teenager and it set the tempo for two decades of pop-punk. The Dream Syndicate and the Cleaners from Venus were both mining the sixties from opposite ends - one Velvets feedback at volume, one cassettes recorded in a bedroom in Essex and mailed out by hand.",
  "1983": "College radio found a house style and Murmur is its founding text: guitars ringing, words deliberately left unintelligible. The same twelve months gave us Madonna's debut, the ugliest record Swans could manage, and Daniel Johnston recording Hi How Are You onto a boombox with a chord organ.",
  "1984": "American independent rock's best year. Zen Arcade, Double Nickels on the Dime and Let It Be all appeared within months of each other on labels with no money, and all three argue that hardcore had become too small to stay inside. Purple Rain and Born in the U.S.A. were the two biggest records in the country and neither is remotely as simple as it was taken to be.",
  "1985": "Hounds of Love has a side of singles and a side about drowning, and Kate Bush produced all of it herself. Elsewhere the guitar turned deliberately unpleasant - Psychocandy buries its melodies under feedback, Bad Moon Rising barely resolves - while Prefab Sprout and Scritti Politti made pop so glossy it reads as critique.",
  "1986": "The Queen Is Dead and Control came out the same year and both are about refusing a role you have been handed. Janet Jackson took over her own career with Jam and Lewis; Morrissey and Marr peaked and knew it. Underneath, Big Black and Sonic Youth were making guitars sound like machinery, and Graceland started an argument about credit that has never quite ended.",
  "1987": "Dinosaur Jr. turned sheer volume into a songwriting device and Sonic Youth's Sister found actual songs inside the tunings. Paid in Full made the sampler a lead instrument, and Rakim's phrasing - rhymes landing anywhere in the bar rather than on the four - is the point where hip-hop's internal rhythm got complicated for good.",
  "1988": "Talk Talk had a hit-single career and spent all of it: Spirit of Eden is hours of improvisation edited down to something nearer chamber music, and the label sued. Daydream Nation and Surfer Rosa are the loud version of the same refusal, and Isn't Anything showed what a guitar could still be talked into doing.",
  "1989": "Straight Outta Compton made hip-hop a national political problem and sold enormously anyway. Doolittle gave loud-quiet-loud its definitive recording, the Stone Roses welded indie guitars to a dance floor, and Bleach came out on Sub Pop with almost nobody paying attention.",
  "1990": "Heaven or Las Vegas is the one Cocteau Twins record that is beautiful and legible at the same time. People's Instinctive Travels offered jazz sampling as the alternative to gangsta rap, and Fear of a Black Planet is the Bomb Squad at their densest - a wall built entirely from other people's records, finished just before sampling law closed that door for good.",
  "1991": "The year the underground got a budget. Nevermind went to number one and Loveless cost a fortune and sold nothing, and both are records that bury the voice on purpose. Spiderland arrived with no explanation and most of post-rock came out of it, while The Low End Theory and Blue Lines showed how much room a rhythm section could hold if you let it.",
  "1992": "Slanted & Enchanted made lo-fi an aesthetic rather than a budget, and Pavement spent years being accused of not meaning it. The Chronic rebuilt hip-hop around live-sounding funk, the Aphex Twin ambient works came out of a teenager's bedroom in Cornwall, and Sade made the smoothest record of a decidedly unsmooth decade.",
  "1993": "The majors had signed everything with a distortion pedal and the results all came due at once. Rid of Me, Last Splash, Exile in Guyville and So Tonight That I Might See are the year's four best guitar records and were all fronted by women, which the press of the time reported as a trend rather than a coincidence. Wu-Tang built 36 Chambers in a basement on the opposite principle entirely, and Yo La Tengo quietly worked out on Painful what the next decade of indie rock would sound like.",
  "1994": "Kurt Cobain died in April and Live Through This came out a week later, which is the fact the rest of the year still gets read through. It deserves better: Illmatic and Ready to Die landed within months of each other and reset what a rap album could be, Portishead and Bark Psychosis found two separate exits from rock, and Guided by Voices made Bee Thousand on a four-track in a basement while Jeff Buckley spent a year getting Grace exactly right. Both methods worked.",
  "1995": "Britpop peaked and American indie stopped paying attention to it. The Bends is where Radiohead learned to write, Post is Bjork refusing to repeat herself, and Slowdive answered shoegaze's commercial collapse with Pygmalion, a record with almost nothing left in it. Elliott Smith's second album is one man and a tape machine.",
  "1996": "R&B and hip-hop were where the production risk was: Timbaland's work for Aaliyah on One in a Million invented a rhythmic language pop is still using thirty years on. Belle and Sebastian put out two albums in one year with no photographs and no interviews, Fishmans built Long Season as a single thirty-five minute piece, and Pinkerton flopped before becoming a religion.",
  "1997": "Millennial dread arrived three years early. OK Computer and Homogenic both set a human voice against machines and reached opposite conclusions about it, while Elliott Smith and Modest Mouse made the year's other two great records with almost nothing. Underneath, electronic music was learning to hold an album together - Dots and Loops, Homework, Monolake's Hong Kong - and Baduizm more or less invented neo-soul single-handed. Then a group of Cuban musicians in their seventies outsold nearly all of it.",
  "1998": "The year hip-hop and R&B stopped asking permission: Miseducation and Aquemini both went platinum without conceding an inch, and Madonna reinvented herself by hiring a drum-and-bass producer. Boards of Canada made the definitive half-remembered-childhood record and Tortoise made post-rock's most elegant one. In the Aeroplane over the Sea sold almost nothing and then spent twenty years becoming the most beloved album on this list.",
  "1999": "The end of something. Emergency & I and Keep It Like a Secret are two of the best guitar records of the nineties and both arrived after the audience for them had moved on, American Football made one album and dissolved, and Play licensed every track it had and turned a blues archive into advertising. Fiona Apple answered a magazine profile with a ninety-word album title.",
  "2000": "The year rock stopped trusting guitars: Kid A traded them for modular synths while Godspeed stretched post-rock to breaking point. But the real centre of gravity was the Soulquarians' Electric Lady sessions - Common, Erykah Badu and Jill Scott turning neo-soul into the most fertile studio scene of the decade - and, on the charts, teen pop at absolute peak power.",
  "2001": "Two futures arrived at once. Downtown New York sent the garage-rock revival out to reclaim the guitar, while Fennesz, Aphex Twin and Bjork dissolved instruments into laptop grain. In between, Timbaland and Aaliyah rebuilt R&B around negative space, and The Microphones proved a four-track in a bedroom could sound enormous.",
  "2002": "The year the internet started deciding things: Wilco streamed the album their label had rejected and won. Grief ran underneath everything - Basinski's tape loops crumbling into an accidental 9/11 elegy - while post-punk revival hardened into a New York house style and Missy Elliott kept dismantling pop from inside it.",
  "2003": "Indie found its mainstream on-ramp. The Postal Service made laptop pop that soundtracked a decade of television, dance-punk turned DFA into a genre, and Death Cab and Sufjan Stevens made earnestness commercially viable. At the far end, Shiina Ringo and Sweet Trip were already treating pop as something to shatter and reassemble.",
  "2004": "Funeral turned indie rock from a subculture into a career path, and the blogs that broke it became the new gatekeepers. Freak-folk was the year's other engine - Animal Collective, Joanna Newsom, Iron & Wine, Sufjan - while Kanye West's debut swapped gangsta postures for soul samples and grad-school anxiety, and M.I.A. built a mixtape out of borrowed global scraps.",
  "2005": "Maximalism everywhere: Sufjan's fifty-states conceit at full orchestral tilt, Animal Collective finding actual songs inside the noise, Kanye hiring Jon Brion for strings. Dance music re-entered indie through the front door with LCD Soundsystem's debut, and Robyn quietly went independent to invent the template for the next decade of sad bangers.",
  "2006": "MySpace made Arctic Monkeys famous before the album existed - and yet the album could still be a monument: Newsom's Ys, Scott Walker's Drift, J Dilla's Donuts finished from a hospital bed. Emo hit its theatrical peak with The Black Parade while Amy Winehouse pulled pop back to 1963, and in the margins Beach House and Tim Hecker began the long drift into haze.",
  "2007": "Radiohead detonated the pricing model with In Rainbows and the industry never quite recovered. Underneath, London's night-bus melancholy and Berlin's loop minimalism gave electronic music a new emotional register, M.I.A. globalised pop's palette, and Bon Iver's cabin handed indie its most durable origin myth.",
  "2008": "Recession-year indie split between escapism and noise. MGMT and Cut Copy chased festival euphoria, Fleet Foxes retreated into close harmony, Vampire Weekend brought Ivy League jangle - while No Age, Vivian Girls and Times New Viking buried their hooks in tape hiss. Lady Gaga's debut announced that pop was about to eat the decade's dance music whole.",
  "2009": "Peak blog era: Animal Collective and Grizzly Bear went from message boards to the Billboard top ten in a single season. The counter-move was already forming - Wavves and Best Coast in a haze of reverb, Neon Indian and Oneohtrix Point Never rebuilding half-remembered television into hypnagogic pop - and The xx made a debut out of almost nothing but space.",
  "2010": "Indie rock's establishment year: The Suburbs took the Grammy and the blogs that broke Arcade Fire suddenly had a seat at the table. The records around it went the other way - Joanna Newsom's three-hour Have One On Me, Sufjan burying his choir under drum machines on The Age of Adz. Beach House and Toro y Moi found the decade's haze, Sleigh Bells found its distortion, and Speak Now was the last Taylor Swift album that still called itself country.",
  "2011": "The year the internet grew its own genres. Macintosh Plus turned mall muzak into vaporwave and Oneohtrix Point Never sampled the same decade into Replica, while Tim Hecker and Grouper pushed ambient toward hymn. Above ground it was a folk year turning strange - Helplessness Blues, Bon Iver's self-titled widescreen rewrite, Destroyer smuggling soft rock back in on Kaputt - and Angel Olsen's first cassette went almost entirely unheard.",
  "2012": "Two debuts in the same season made the decade's shape clear: channel ORANGE gave R&B a first-person novelist, Visions built pop out of bedroom software. Fiona Apple returned with The Idler Wheel and no interest in being liked, Tame Impala went fully interior on Lonerism, and Lana Del Rey survived the year's ugliest backlash. On Bandcamp, Alex G and Mitski were quietly putting out their first records.",
  "2013": "The surprise release became a weapon - BEYONCÉ arrived overnight and rewrote the rollout - while Daft Punk spent a fortune on session musicians to make Random Access Memories sound analogue. Vampire Weekend finally got serious, Blood Orange made a night-bus record out of New York, and a seventeen-year-old from Auckland turned teenage boredom into Pure Heroine.",
  "2014": "Everything hardened. FKA Twigs built LP1 out of silence and sub-bass, Swans made two hours of ritual on To Be Kind, and Aphex Twin ended a thirteen-year absence with Syro. Taylor Swift dropped the pretence and made a pop album; Angel Olsen and Mitski both plugged in for the first time. Grouper's Ruins was the counterweight - a piano, a room, a refrigerator hum.",
  "2015": "Kendrick made the decade's most ambitious record and pop criticism finally caught up with pop: E•MO•TION became a canonical album, Grimes made Art Angels for the charts, and Father John Misty sang about marriage like a man selling one. Beach House released two albums two months apart, Courtney Barnett talked her way through a whole record, and Natalia Lafourcade returned to Latin American folk roots.",
  "2016": "A grief year that made monuments. Blonde emptied out everything channel ORANGE had filled in, Bon Iver ran his voice through the Messina and came out numbered and glitching, and Radiohead released a song they'd been holding for twenty years. Solange and Blood Orange made records about being Black in America that were also the year's most beautiful; Angel Olsen simply wrote the songs. Big Thief and Japanese Breakfast started here.",
  "2017": "Melodrama turned a breakup into architecture and SZA turned indecision into Ctrl, the two records that defined what confessional pop could carry. Tyler came out sideways on Flower Boy, Jay-Z answered Lemonade in public, and St. Vincent made latex-and-neon art pop. In the margins Charli XCX put out Pop 2 as a mixtape and accidentally drew the blueprint for the next five years.",
  "2018": "The deepest year on the list, and the one where the edges came to the centre. Two film scores lead it - Greenwood's Phantom Thread, Britell's Beale Street - and behind them a wave of first and second records by women who would define the next decade: Mitski, Snail Mail, Lucy Dacus, Haley Heynderickx, boygenius formed almost as an afterthought. Robyn returned after eight years, ROSALÍA rebuilt flamenco as pop, and Kacey Musgraves made Nashville sound like a disco.",
  "2019": "The decade closed on its own mythology. MAGDALENE and Norman Fucking Rockwell! were both about being cast as a character; IGOR and All Mirrors both buried the voice in arrangement. Weyes Blood wrote Laurel Canyon for the end of the world, Big Thief put out two albums in seven months, and 100 gecs and Billie Eilish arrived from opposite directions to say the same thing - the next decade's pop would be made at home, and it would be loud.",
  "2020": "The year the room became the studio. Adrianne Lenker recorded songs in a cabin with one microphone, Charli XCX made how i'm feeling now in six weeks on Zoom, and Fiona Apple banged on the walls of her house for Fetch The Bolt Cutters - three answers to the same confinement. Taylor Swift wrote two albums in it. Ichiko Aoba went the other way entirely, imagining an island in full orchestral detail.",
  "2021": "Everything reopened and nothing sounded settled. Black Country, New Road and Injury Reserve both made debuts out of collapse - one theatrical, one built from the wreckage of a bandmate's death - while Low ran thirty years of songcraft through digital distortion on HEY WHAT. Cassandra Jenkins turned a field recording into the year's most consoling record, and Tyler and Little Simz proved rap's long-form ambitions were intact.",
  "2022": "A guitar year that refused to be a rock year. Big Thief sprawled across four studios and twenty songs, Black Country, New Road released their best album with the singer already gone, and Jockstrap and Gilla Band took the instrument apart on principle. Beyoncé opened RENAISSANCE onto the dance floor and returned house to the people who built it; ROSALÍA and Natalia Lafourcade pulled in opposite directions and both won.",
  "2023": "The year of the late-career record. ANOHNI, Sufjan, Feist, Lana Del Rey and Mitski all made albums about grief and endurance that were better than their famous ones. Underneath, a younger and noisier bench - feeble little horse, Model/Actriz, Wednesday, L'Rain - treated genre as something to be scraped at, and billy woods and Kenny Segal made the decade's most quietly devastating rap record.",
  "2024": "BRAT took over the summer and the discourse, which made it easy to miss how strange the rest of the year was. Cindy Lee put out two hours of the best pop music of the decade on a GeoCities page and nowhere else, Nicolas Jaar released two records at once, and Jessica Pratt and Haley Heynderickx made small perfect things at the far end from all of it. The log thins out after this.",
  "2025": "A year of second acts and left turns. Rosalia followed a flamenco-reggaeton blockbuster with LUX, an orchestral record sung in a dozen languages, and Lorde stripped Virgin back to almost nothing after the sunshine of Solar Power. FKA twigs put out Eusexua and then a companion record ten months later, treating the album as something you can keep adding to.",
  "2026": "Four records here arrive after long silences: American Football at twenty-seven years, Boards of Canada at twenty-four, Madonna at twenty-one, Bill Callahan at seventeen. Inferno is the one that sounds like no time passed at all - twenty-four years off and it still opens the year. The top is otherwise thick with first-timers, Lip Critic and Slayyyter and a Nirosta Steel record that sounds assembled behind a closed door. A third of the year still to go."
};
